      "id": "ouzhen599-object-metaphor-4panel-campaign",
      "source": "https://x.com/ou_zhen599/status/2079838167637860671",
      "author": "ou_zhen599",
      "date": "2026-07-22",
      "lang": "zh",
      "target_model": "GPT-image 2",
