      "id": "diplomeme-finished-poster-not-photo-with-type",
      "source": "https://x.com/Diplomeme/status/2082514119589269610",
      "author": "Diplomeme",
      "date": "2026-08-01",
      "lang": "en",
      "target_model": "GPT Image 2",
